package com.college.erp.model.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="attendance_records")
public class AttendanceRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String rollNo,studentName,course,subjectCode,subjectName,section,status,markedBy; LocalDate date; String time; public Long getId(){return id;} public void setIdForApi(Long v){id=v;} public String getRollNo(){return rollNo;} public void setRollNo(String v){rollNo=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getCourse(){return course;} public void setCourse(String v){course=v;} public String getSubjectCode(){return subjectCode;} public void setSubjectCode(String v){subjectCode=v;} public String getSubjectName(){return subjectName;} public void setSubjectName(String v){subjectName=v;} public String getSection(){return section;} public void setSection(String v){section=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getMarkedBy(){return markedBy;} public void setMarkedBy(String v){markedBy=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public String getTime(){return time;} public void setTime(String v){time=v;} }
